using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var rows=new List<object>();foreach(uint seed in new uint[]{17,12345,987654321,4294967295})foreach(var size3D in new[]{false,true})foreach(var rotation3D in new[]{false,true}){var go=new GameObject("main-init-probe"){hideFlags=HideFlags.HideAndDontSave};try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.playOnAwake=false;m.startLifetime=new ParticleSystem.MinMaxCurve(0,1);m.startSpeed=new ParticleSystem.MinMaxCurve(0,1);m.startSizeX=new ParticleSystem.MinMaxCurve(0,1);m.startSizeY=new ParticleSystem.MinMaxCurve(0,1);m.startSizeZ=new ParticleSystem.MinMaxCurve(0,1);m.startSize3D=size3D;m.startRotation3D=rotation3D;m.startRotationX=new ParticleSystem.MinMaxCurve(0,Mathf.PI*2);m.startRotationY=m.startRotationX;m.startRotationZ=m.startRotationX;m.startColor=new ParticleSystem.MinMaxGradient(new Color(1,0,0,1),new Color(1,1,0,1));var em=ps.emission;em.enabled=false;var sh=ps.shape;sh.enabled=false;ps.useAutoRandomSeed=false;ps.randomSeed=seed;ps.Play();ps.Pause();ps.Emit(17);var p=new ParticleSystem.Particle[17];ps.GetParticles(p);var values=new List<object>();foreach(var v in p)values.Add(new{seed=v.randomSeed,lifetime=v.startLifetime,speed=v.velocity.z,size=new[]{v.startSize3D.x,v.startSize3D.y,v.startSize3D.z},rotation=new[]{v.rotation3D.x,v.rotation3D.y,v.rotation3D.z},green=v.startColor.g});rows.Add(new{seed,size3D,rotation3D,particles=values});}finally{UnityEngine.Object.DestroyImmediate(go);}}File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,rows}));return "Main initialization cases="+rows.Count;}}

